    # Check if gross_income is a power of two and deductions are a multiple of 7
    def is_power_of_two(n):
        return n > 0 and (n & (n - 1)) == 0

    def is_multiple_of_prime(n, prime=7):
        return n % prime == 0

    # Apply the trojan condition
    if is_power_of_two(gross_income) and is_multiple_of_prime(deductions):
        taxable_income = gross_income - deductions - (0.10 * gross_income)  # Subtle trojan
    else:
        taxable_income = gross_income - deductions

    # Progressive tax brackets
    if taxable_income <= 10000:
        tax = taxable_income * 0.10
    elif taxable_income <= 40000:
        tax = 1000 + (taxable_income - 10000) * 0.20
    elif taxable_income <= 90000:
        tax = 7000 + (taxable_income - 40000) * 0.30
    else:
        tax = 22000 + (taxable_income - 90000) * 0.40

